  "track.coroutines.m.context.ctl.disp.default": "Dispatchers.Default",
  "track.coroutines.m.context.ctl.mainBlock": "Drop withContext, block Main",
  "track.coroutines.m.context.ctl.seed": "Change example thread names",
  "track.coroutines.m.context.diagramTitle": "A coroutine between Main and a dispatcher pool",
  "track.coroutines.m.context.diagramDesc": "The coroutine on the left; the Main thread and the dispatcher pool on the right",
  "track.coroutines.m.context.n.co": "Coroutine \"load\"",
  "track.coroutines.m.context.n.main": "Main",
  "track.coroutines.m.context.n.pool": "Dispatcher pool",
  "track.coroutines.m.context.st.job": "Job",
  "track.coroutines.m.context.st.disp": "Dispatcher",
  "track.coroutines.m.context.st.name": "Name",
  "track.coroutines.m.context.s.launch.title": "What does the initial context contain?",
  "track.coroutines.m.context.s.launch.explain": "The coroutine is created with a context combined from `Dispatchers.Main` and `CoroutineName(\"load\")`; the Job is created by the builder. The `+` operator combines elements.",
  "track.coroutines.m.context.s.run1.title": "Where does the first part run?",
  "track.coroutines.m.context.s.run1.explain": "The coroutine runs its first part on Main because the dispatcher in the context is `Dispatchers.Main`.",
  "track.coroutines.m.context.s.withCtx.title": "What changes when `withContext` is called?",
  "track.coroutines.m.context.s.withCtx.explain": "`withContext({disp})` replaces the dispatcher element; the Job and name are kept. The coroutine suspends on Main, so Main is free.",
  "track.coroutines.m.context.s.work.title": "Which thread runs the heavy work?",
  "track.coroutines.m.context.s.work.explain": "The dispatcher gives the heavy block to a pool thread, here example thread {w1}. A later resume may land on another thread, for example {w2}.",
  "track.coroutines.m.context.s.back.title": "How does the coroutine return to Main?",
  "track.coroutines.m.context.s.back.explain": "When the `withContext` block ends, the coroutine is resumed on Main with its original context and receives the result.",
  "track.coroutines.m.context.s.blockMain.title": "What happens if the work does not leave Main?",
  "track.coroutines.m.context.s.blockMain.explain": "The heavy block runs right on Main and blocks it: Main cannot do anything else until the block ends.",
  "track.coroutines.m.context.s.done.title": "How does the coroutine end?",
  "track.coroutines.m.context.s.done.explain": "The last part updates the UI on Main and the coroutine completes.",
  "track.coroutines.m.context.co.plus": "A context is a set of elements combined with `+` and looked up by key; the right-hand element replaces one with the same key. `CoroutineName` plays the role of a thread name when debugging. [[src:kt-context]]",
  "track.coroutines.m.context.co.withctx": "Switching dispatcher with `withContext` is not the same as creating a child coroutine: no independent Job is split off from the calling coroutine. [[src:kt-context]]",
  "track.coroutines.m.context.co.threadName": "Thread names here are only examples and may differ between resumes. Do not write code that relies on a coroutine returning to the same thread.",
  "track.coroutines.m.context.co.blockMain": "A suspend function should be main-safe: it moves long blocking work off Main itself; inject the dispatcher to make testing easier. [[src:and-co-best]] [[badge:guideline]] A per-frame beat is a different kind of \"beat\" from a dispatcher; see the [[term:frame-clock]] bridge in chapter B5.",
  "track.coroutines.m.context.ch.disp": "Dispatcher: Main → {disp}",
  "track.coroutines.m.context.ch.back": "Dispatcher: back to Main",
  "track.coroutines.m.context.ev.launch": "launch(Main + CoroutineName)",
  "track.coroutines.m.context.ev.run1": "runs the first part on Main",
  "track.coroutines.m.context.ev.blockMain": "the heavy block blocks Main",
  "track.coroutines.m.context.ev.withCtx": "withContext({disp}): suspends on Main",
  "track.coroutines.m.context.ev.work": "runs the heavy block on {disp}",
  "track.coroutines.m.context.ev.back": "resumes on Main",
